effect.shader:
float hash12(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
    vec2 res = acScreenSize;
    vec2 uv  = acScreenNorm;

    // ---- Scanline with angle ----
    float ang = radians(scanAngle);
    vec2 dir = vec2(cos(ang), sin(ang));
    float scanCoord = dot(uv * res, dir);

    float scanline = sin((scanCoord - progress * scrollSpeed) / max(scanlineHeight, 1.0));
    vec3 vhsColor = scanColor.rgb * scanline * scanlineIntensity;

    // Grain
    vec2 grainSeed = vec2(12.9898, 78.233) + progress * grainTimeScale;
    float grain = fract(sin(dot((uv * res) * uv, grainSeed)) * 43758.5453);
    vhsColor += vec3(grain) * grainIntensity;

    // Glitch
    vec2 tuv = uv;
    if (glitchPhase < glitchProbability) {
        float gx = (fract(sin(progress * 12.9898) * 43758.5453) - 0.5) * glitchIntensityX;
        float gy = (fract(cos(progress * 78.233) * 43758.5453) - 0.5) * glitchIntensityY;
        tuv += vec2(gx, gy);
    }

    // Vertical band
    float bandNoise = hash12(uv * res);
    vec3 chromaColor = texture2DCv(inputImg.texture, tuv).rgb;

    if (abs(uv.y - bandPos) < bandHeight) {
        float rs = bandNoise * bandChoppiness;
        vhsColor += vec3(rs) * staticAmount;

        tuv.x += sin(uv.y * res.y * 10.0 + rs) * warpFactor;

        chromaColor = vec3(
            texture2DCv(inputImg.texture, tuv + vec2(chromaAmount * rs, 0.0)).r,
            texture2DCv(inputImg.texture, tuv).g,
            texture2DCv(inputImg.texture, tuv - vec2(chromaAmount * rs, 0.0)).b
        );

        vhsColor = mix(vhsColor, chromaColor, bandIntensity * (1.0 - rs));
    }

    vec3 originalColor = texture2DCv(inputImg.texture, tuv).rgb;
    gl_FragColor = vec4(mix(originalColor, vhsColor, blendFactor), 1.0);
}
